INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
  (55122, 0, 0, 'Did you recover the first aid kits? Don''t take the murlocs lightly.', 0),
  (55174, 0, 0, 'Please... I need... some food...', 0),
  (55879, 0, 0, 'Please... help! I won''t last much longer!', 0),
  (55990, 0, 0, 'So, these were the stones used to bind me? The ogres clearly were concerned about you thwarting their plans.', 0),
  (56775, 0, 0, 'Don''t be shy. Just walk up to the target dummies, select them, and use your main attack.', 0),
  (59350, 0, 0, 'Come. The spirits of nature await us.', 0),
  (59355, 0, 0, 'Did you get the supplies needed? Meredy should have the ice mote, while the other two should be nearby.', 0),
  (59926, 0, 0, 'Do not bother me! Go and attack those combat dummies. Show me your power.', 0),
  (59929, 0, 0, 'The murlocs are carrying our first aid kits. Slay them and bring all of the kits to me.', 0),
  (59932, 0, 0, 'Please... I be needin''... food...', 0),
  (59970, 0, 0, 'I see you have the grimoire that enacted the binding ritual.', 0),
  (59981, 0, 0, 'These were the ward stones used to bind me? Perhaps even the ogres have heard tale of my strength!', 0);
